//Create product
function* createUser(payload) {
  console.log("pl", payload);
  const apiCall = () => {
    return axios
      .post(`authentication/register/entity`, payload.payload, tokenConfig())
      .then((response) => response.data)
      .catch((err) => {
        throw err;
      });
  };

  try {
    const response = yield call(apiCall);
    console.log("RESP", response);
    yield put(createUserSuccess(response));
  } catch (error) {
    let message;
    console.log("error", error.response);

    switch (error.status) {
      case 500:
        message = "Internal Server Error";
        break;
      case 401:
        message = "Invalid credentials";
        break;
      default:
        message = error;
    }
    yield put(createUserFailed(message, error.response.data.data.errors));
  }
}

//Update product
function* updateUser(payload) {
  console.log("bayl", payload);
  const apiCall = () => {
    return axios
      .patch(
        `authentication/users/${payload.payload.id}/update`,
        payload.payload.data,
        tokenConfig()
      )
      .then((response) => response.data)
      .catch((err) => {
        throw err;
      });
  };

  try {
    const response = yield call(apiCall);
    console.log("At Update User:", response);
    yield put(updateUserSuccess(response));
  } catch (error) {
    // console.log('At Update User:', error.response);
    yield put(
      updateUserFailed(error.response.data.detail, error.response.data.errors)
    );
  }
}

