//Get users
export function* watchGetUser() {
  yield takeEvery(GET_USERS, getUsers);
}
//Get entity customers
export function* watchGetCompanyCustomers() {
  yield takeEvery(GET_COMPANY_CUSTOMERS, getCompanyCustomers);
}
//Get profile
export function* watchGetProfessionals() {
  yield takeEvery(GET_PROFESSIONALS, getProfessionals);
}

//Add profile
export function* watchAddUser() {
  yield takeEvery(CREATE_USER, createUser);
}

//Update profile
export function* watchUpdateUser() {
  yield takeEvery(UPDATE_USER, updateUser);
}

//Verify profile
export function* watchVerifyUser() {
  yield takeEvery(VERIFY_USER, verifyUser);
}

//Search profile
export function* watchSearchUser() {
  yield takeEvery(SEARCH_USERS, searchUser);
}
//get user by ID
export function* watchgetUserById() {
  yield takeEvery(GET_USER_BY_ID, getUserById);
}
//get user by phone
export function* watchgetUserByPhone() {
  yield takeEvery(GET_USER_BY_PHONE, getUserByPhone);
}
//Blanket users action
export function* watchUsersAction() {
  yield takeEvery(USERS_ACTION, usersAction);
}
//Blanket users action
export function* watchUsersActionAdmin() {
  yield takeEvery(USERS_ACTION_ADMIN, usersActionAdmin);
}
//Upload user images
export function* watchUploadUserImages() {
  yield takeEvery(UPLOAD_USER_IMAGES, uploadUserImages);
}
//Upload user images
export function* watchUploadUserDocuments() {
  yield takeEvery(UPLOAD_USER_DOCUMENTS, uploadUserDocuments);
}

function* profilesSaga() {
  yield all([
    fork(watchGetUser),
    fork(watchGetCompanyCustomers),
    fork(watchGetProfessionals),
    fork(watchAddUser),
    fork(watchSearchUser),
    fork(watchgetUserById),
    fork(watchgetUserByPhone),
    fork(watchUpdateUser),
    fork(watchVerifyUser),
    fork(watchUsersAction),
    fork(watchUsersActionAdmin),
    fork(watchUploadUserImages),
    fork(watchUploadUserDocuments),
  ]);
}

export default profilesSaga;
